/**
 * Resolves the packaged artwork for a catalog entry.
 *
 * @param slug - The `image` slug carried by the entry, if any.
 * @returns The packaged asset URL, or undefined when the entry has none.
 */
export const getResourceIcon = (
  slug: string | undefined,
): string | undefined =>
  slug ? RESOURCE_ICONS[slug] : undefined;
